import {
  app,
  BrowserWindow,
  ipcMain,
  shell,
  systemPreferences,
  screen,
} from "electron";
import path from "path";
import { DatabaseSync } from "node:sqlite";
import os from "os";
import { spawn, exec } from "child_process";
import { promisify } from "util";

const execAsync = promisify(exec);

// This allows TypeScript to pick up the magic constants that's auto-generated by Forge's Vite
// plugin that tells the Electron app where to look for the Vite-bundled app code (depending on
// whether you're running in development or production).
declare const MAIN_WINDOW_VITE_DEV_SERVER_URL: string;
declare const MAIN_WINDOW_VITE_NAME: string;

// Handle creating/removing shortcuts on Windows when installing/uninstalling.
if (require("electron-squirrel-startup")) {
  app.quit();
}

const CHAT_DB_PATH = path.join(os.homedir(), "Library/Messages/chat.db");

// Contact cache to avoid re-lookups
const contactCache = new Map<string, string>(); // phone number -> contact name
let contactMap: Map<string, string> | null = null;
let contactMapLoading = false;

// Store the original bottom position to keep it fixed during resizes
let originalBottomY: number | null = null;

const createWindow = (): void => {
  // Get screen dimensions
  const { width: screenWidth, height: screenHeight } = screen.getPrimaryDisplay().workAreaSize;
  
  const windowWidth = 600;
  const windowHeight = 200;
  const bottomMargin = 2; // Distance from bottom of screen
  
  // Calculate position: centered horizontally, at bottom vertically
  const x = Math.floor((screenWidth - windowWidth) / 2);
  const y = screenHeight - windowHeight - bottomMargin;
  
  // Create the browser window.
  const mainWindow = new BrowserWindow({
    width: windowWidth,
    height: windowHeight,
    x: x,
    y: y,
    frame: false,
    transparent: true, // Remove backdrop shadow
    hasShadow: false, // Remove window shadow on macOS
    backgroundColor: '#00000000', // Fully transparent background
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      nodeIntegration: false,
      contextIsolation: true,
    },
  });

  // and load the index.html of the app.
  if (MAIN_WINDOW_VITE_DEV_SERVER_URL) {
    mainWindow.loadURL(MAIN_WINDOW_VITE_DEV_SERVER_URL);
  } else {
    mainWindow.loadFile(
      path.join(__dirname, `../renderer/${MAIN_WINDOW_VITE_NAME}/index.html`)
    );
  }

  // Store the original bottom position once window is ready
  mainWindow.once('ready-to-show', () => {
    const cb = mainWindow.getContentBounds();
    originalBottomY = cb.y + cb.height;
  });

  // Open the DevTools.
  if (!app.isPackaged) {
    mainWindow.webContents.openDevTools();
  }
};

// This method will be called when Electron has finished
// initialization and is ready to create browser windows.
// Some APIs can only be used after this event occurs.
app.on("ready", createWindow);

// Quit when all windows are closed, except on macOS. There, it's common
// for applications and their menu bar to stay active until the user quits
// explicitly with Cmd + Q.
app.on("window-all-closed", () => {
  if (process.platform !== "darwin") {
    app.quit();
  }
});

app.on("activate", () => {
  // On OS X it's common to re-create a window in the app when the
  // dock icon is clicked and there are no other windows open.
  if (BrowserWindow.getAllWindows().length === 0) {
    createWindow();
  }
});

